INSERT INTO "citation_mining" ("slug", "local_ref_id", "global_ref_id", "doi", "backward", "forward", "connections_produced", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "deferred_reason") VALUES ('accessible-circulation-geometry', 'RAMP-HIST-01', 'REF-01005', NULL, 1, 0, '[]', NULL, '2026-09-18 23:57', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', '2026-09-18 23:57', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', 'DEPTH-1 DEFERRAL (citation-miner section 6), design rather than capacity: REF-01005 was admitted THIS batch, so mining it here would be depth-2 in one pass. Legitimate under the owner ruling of 2026-09-18 ("deferred is okay so long as it runs eventually"), and ASSIGNED rather than left to age — THE NEXT BATCH TAKES IT AND IT IS THE HIGHEST-VALUE BACKWARD TARGET ON THIS SLUG. Reason: Table 13 footnote c names Templer 1977 and Walter 1971 as the warrants for its recommendation table, and the Comparison section names Elmer 1957, so its reference list is the index to the entire pre-1990 ramp-gradient layer GAP-028 identified as structurally unreachable — held by a document this project now has in full. NOTE THE RETRIEVAL ASYMMETRY, because it changes what a mining pass means here: no Crossref deposit exists, so there is NO machine-readable reference list. The pass runs against the PDF bibliography (page indices 167 onward, OCR damaged), not against an API, and a yield from it must name a screen from governance/mining-screens.yaml and be derived by scripts/research/mining_screen.py per the owner rule of 2026-09-18 22:55.');
INSERT INTO "evidence_sources" ("ref_id", "source_type", "author_count", "author_count_is_complete", "first_author_last", "first_author_first", "is_corporate_primary", "author_display", "pub_year", "pub_year_note", "pub_title", "pub_subtitle", "chapter_title", "original_title", "lang_detected", "lang_detection_method", "pub_title_en", "pub_subtitle_en", "chapter_title_en", "journal_name_en", "translation_method", "translation_reviewed", "journal_name", "journal_abbrev", "volume", "issue", "pages_start", "pages_end", "article_number", "publisher", "publisher_location", "edition", "book_title", "series", "series_number", "report_number", "institution", "standard_number", "doi", "pmid", "pmcid", "isbn", "issn", "url", "url_accessed", "handle", "local_id", "tier", "evidence_type", "jurisdiction", "co1_provenance", "co1_source_type", "synthesis_attribution_required", "metadata_quality", "verification_status", "doi_resolution_outcome", "bpc_shorthand", "bpc_note", "grey_flag", "grey_reason", "verification_note", "prior_expectation", "search_queries_used", "derivation_chain", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "verified_by_tool", "last_verified_at", "verification_attempt_count", "superseded_by_ref_id", "pages", "pub_month", "language", "subtype", "citation_count", "url_resolution_outcome", "url_last_fetched", "url_match_similarity", "metadata_integrity_status", "metadata_integrity_detail", "code_currency_status", "code_currency_verified_at", "code_currency_verified_by_session", "code_currency_notes", "scope", "data_capture_status", "citation_mining_status", "processing_blocked_reason", "standard_number_note", "author_display_note", "publisher_note", "verification_disposition", "verification_method", "verification_closure_reason") VALUES ('REF-01005', 'report', NULL, 0, NULL, NULL, 0, NULL, 1979, NULL, 'Accessible buildings for people with walking and reaching limitations', NULL, NULL, NULL, 'en', 'payload', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'U.S. Department of Housing and Urban Development, Office of Policy Development and Research; for sale by the Supt. of Docs., U.S. Govt. Print. Off.', 'Washington, D.C.', NULL, NULL, 'HUD-PDR', '397', NULL, 'Syracuse University, N.Y.', NULL, NULL, NULL, NULL, NULL, NULL, 'https://files.eric.ed.gov/fulltext/ED184280.pdf', '2026-09-18', NULL, NULL, 3, 'grey', 'US', NULL, NULL, NULL, 'COMPLETE', 'VERIFIED', NULL, NULL, NULL, 1, 'US federal research report issued by HUD Office of Policy Development and Research under contract H-2200 to Syracuse University; not peer-reviewed. Indexed by ERIC as ED184280; no DOI, no Crossref deposit, no PMID.', NULL, NULL, NULL, NULL, NULL, '2026-09-18 23:48', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', '2026-09-18 23:57', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', 'eric', NULL, 1, NULL, '169', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'intrinsic', 'captured', 'deferred', NULL, NULL, NULL, NULL, 'CLOSED', 'tool', NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-037', 'EG', 'P1', 'OPEN', 'multilingual-research', NULL, 'GAP-028 IS ANSWERED, AND THE ANSWER IS THAT 1:12 WAS MEASURED AND FOUND WANTING BEFORE IT WAS ADOPTED. GAP-028 asked whether the 1:12 threshold is anchored in measurement. REF-01005 (Steinfeld, Schroeder and Bishop 1979, HUD-PDR 397, ERIC ED184280, full text retrieved and persisted this batch) settles it. (1) THE MEASUREMENT EXISTS. A purpose-built adjustable 40-foot ramp, 124 disabled participants, slope stepped 1:12 then 1:16 then 1:20, success judged on distance, time and pulse recovery to within ten beats of resting. (2) IT FOUND 1:12 INADEQUATE: almost half the wheelchair users could not negotiate the full length at 1:12 and about a third could not travel even 5 feet; every wheelchair user completed 40 feet at 1:20, though only three reached that trial. (3) THE STUDY WAS COMMISSIONED TO IMPROVE THE VERY STANDARD THAT CARRIES 1:12 — its Foreword says the six-report series was sponsored to make buildings accessible "through improving the American National Standards Institute A117 standard". (4) ITS OWN RECOMMENDATION TABLE RESTS PARTLY ON OTHERS: Table 13 footnote c reads "Based on research of others (Templer, 1977 and Walter, 1971)", so the chain has three nodes and this project holds one. (5) WALTER 1971 AND STEINFELD 1979 CONVERGE at 1:16 over 20 feet for at least 95 percent of wheelchair users, per page 163 — held on Steinfeld testimony alone, so it is ONE document counted once until Walter is retrieved. WHAT THIS DOES NOT DO: it does not supply a current anchor. Owner ruling 2026-09-18 places 1979 work as historical grounding rather than a present standard, so REF-01005 is admitted T3 grey and parameter 3 x MOB stays undetermined. WHAT IS NOW OWED: retrieve Walter 1971 (candidate 109, record verified) and Templer 1977 (candidate 115) — the two remaining nodes of the chain. Derive the state rather than quoting this: select disposition, title from search_candidates where candidate_id in (109,110,111,115).', '2026-09-18 23:56', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', '2026-09-18 23:56', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-038', 'SW', 'P2', 'OPEN', 'governance', NULL, 'THE SEVENTH CAPTURE-PATH BLINDNESS, AND IT WAS FOUND BY THE ROW IT BROKE. add-source could not write source_type, institution, publisher, publisher_location, book_title, series, series_number, report_number, grey_flag or grey_reason — every field that makes a REPORT citable. REF-01005 is a US federal research report and landed with nine payload-supplied fields NULL under metadata_quality=COMPLETE; a bibliography compiled from that row could not name what the document is. FIXED THIS BATCH by extending _ES_COLS and the argparse surface, per the owner rule of 2026-09-18 22:55 (when the CLI cannot reach a column, add the verb; do not claim the write happened). WHAT IS NOT FIXED AND IS THE REASON THIS IS FILED RATHER THAN CLOSED: (1) nothing DETECTS the class. The _ES_COLS comment block now enumerates seven instances, each found by a session tripping over it, never by a check. The general form is a gate comparing the sanctioned writer reachable column set against the live table columns, and it does not exist. (2) report_number is deliberately still NULL on REF-01005: the OCR of the report-number field is corrupt and Open Library states the number as a series, so it was not invented. (3) evidence_type=grey with grey_flag=0 was the state the first insert produced — two columns holding the same fact and disagreeing, which is rule 5 in miniature and is why grey_flag rides with the venue set now.', '2026-09-18 23:56', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', '2026-09-18 23:56', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-039', 'SW', 'P2', 'OPEN', 'governance', NULL, 'GAP-007 IS CLOSED, AND THE DEFECT WAS WORSE THAN GAP-007 DESCRIBED IT. GAP-007 recorded that relate-extraction lacks --verbatim-exempt while add-extraction has it. The live shape was sharper: add-extraction ACCEPTS --verbatim-exempt and never passed it to _write_relation_edge, so the relation quote check refused with a message instructing the reader to pass a flag that could not reach it. A CORRECT INSTRUCTION TO AN IMPOSSIBLE ACTION IS WORSE THAN A MISSING FLAG, because the only ways past it were to abandon a true extraction or to weaken the check for every source. IT BITES EXACTLY WHERE THE EVIDENCE IS OLDEST: quote_in_artefacts cannot decode a scanned PDF text layer, so no quote from a microfiche-era report can ever match byte-for-byte, and the entire pre-1990 layer GAP-028 names is that shape. FIXED: the exemption is threaded through, still refused without a reason, and the reason is ledgered onto the relation row notes. The artefact must still exist and still be bound to the ref_id — what stops being required is byte-equality against bytes that cannot be decoded at all. WHAT REMAINS OWED: relate-extraction and derive-extraction call the same writer and still expose no flag of their own, so a standalone edge over an undecodable payload is still blocked. Derive it: grep -n "verbatim_exempt" scripts/db.py.', '2026-09-18 23:56', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', '2026-09-18 23:56', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (78, 'accessible-circulation-geometry', NULL, 'EN', 3, 'grey', 'intrinsic', 'https://api.ies.ed.gov/eric/?search="Accessible Buildings for People with Walking and Reaching Limitations"&format=json&rows=10', NULL, 'eric', 'scoping', NULL, 1, 1, 1, 'partial', NULL, NULL, 0, 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', '2026-09-18 23:49', 'HIT, AND IT IS THE BATCH. ERIC ED184280 = Steinfeld, Schroeder and Bishop 1979, HUD-PDR 397. The ERIC abstract itself names "ramps (maximum slopes)" as a data-producing section. Full text then retrieved from files.eric.ed.gov/fulltext/ED184280.pdf — 170 pp, 5702293 bytes, sha256 5dd866a236fb59788dbff4b4ca80c4da8890274259b0cb6941a83c1c370fb751, persisted via retrieval_log.fetch. THE SOURCE HAS NO DOI, NO PMID AND NO CROSSREF DEPOSIT, which is why six batches of DOI-keyed searching on this slug never reached it. Derive the engine spread rather than quoting it: select engine,count(*) from search_executions where slug=(this slug) group by 1.', 0, 'Q4 prior, committed 9cf59e3 BEFORE running: Steinfeld 1979 locatable p~0.75 — a well-indexed figure, likely a HUD or federal report, and the single most likely of the five to be the proximate source the US codes drew on. ERIC was not named as the route when the prior was written; the prior was about the TARGET, not the instrument.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (79, 'accessible-circulation-geometry', NULL, 'EN', 3, 'grey', 'intrinsic', 'https://archive.org/advancedsearch.php?q="wheelchair ramps" AND date:[1950-01-01 TO 1975-12-31]&rows=25&output=json', NULL, 'archive-org', 'scoping', NULL, 2, 2, 0, NULL, NULL, NULL, 0, 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', '2026-09-18 23:49', 'ZERO-YIELD ON TARGET. Two hits, neither relevant: ERIC_ED113892 (the same 1975 school bio-engineering report) and C123305828 (a Berkeley community development block grant document). GENUINE ABSENCE for this query shape — IA full-text search reaches only what has been digitised AND OCRd, and none of the five named pre-1990 items is in that set. Not a query-shape failure: the phrase is the subject term and the date window is correct.', 0, 'Q1/Q2 priors: pre-1975 items locatable p~0.6-0.65. Internet Archive holds digitised government and institutional reports, so a date-bounded topical query is the natural first cut at the pre-1990 layer GAP-028 names.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (80, 'accessible-circulation-geometry', NULL, 'EN', 3, 'grey', 'intrinsic', 'https://api.ies.ed.gov/eric/?search="wheelchair ramps"&format=json&rows=25', NULL, 'eric', 'scoping', NULL, 1, 1, 0, NULL, NULL, NULL, 0, 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', '2026-09-18 23:49', 'NEAR-ZERO-YIELD, and the R14 diagnosis is WRONG INDEX rather than query shape or genuine absence. One hit, ED113892 (Bio-Engineering Services to the Developmentally Disabled Adolescent, 1975), which mentions wheelchair ramps only as an adaptive device in a school programme — off-slug. ERIC is an EDUCATION index: it held Steinfeld 1979 because that report was deposited there, not because ERIC covers built-environment research. SO ERIC IS A HIGH-PRECISION ROUTE TO A NAMED REPORT AND A POOR ROUTE FOR TOPICAL DISCOVERY IN THIS DOMAIN. Both halves are findings of this batch; neither was known before it, and the owner ruling recorded 2026-09-18 states the first half.', 0, 'Expect a handful of rehabilitation-engineering reports: ERIC indexes education and rehabilitation grey literature, so a bare topical phrase should surface the pre-1990 layer if ERIC holds it.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (81, 'accessible-circulation-geometry', NULL, 'EN', 3, 'grey', 'intrinsic', 'https://catalog.hathitrust.org/Search/Home?lookfor=specifications+of+wheelchair+ramps&type=all  [and the companion lookfor=four+architectural+movement+studies+wheelchair]', NULL, 'hathitrust', 'scoping', NULL, 0, 0, 0, NULL, NULL, NULL, 0, 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', '2026-09-18 23:50', 'ZERO-YIELD, AND THE INSTRUMENT IS BAD RATHER THAN THE INDEX EMPTY — this is an R14 query-shape failure of a kind R14 does not name. Both requests returned HTTP 200 carrying a Cloudflare interstitial: "Just a moment... Enable JavaScript and cookies to continue" (5696 and 5753 bytes, persisted). A 200 THAT CONTAINS NO RESULTS IS NOT EVIDENCE OF ABSENCE, and scoring it as one would have been the same error batch 17 caught on JSTOR, where a 200 body was a bot interstitial. NOTHING IS CONCLUDED ABOUT WHAT HATHITRUST HOLDS. The owner ruling of 2026-09-18 records the instrument as known-bad for this purpose.', 0, 'Q1/Q2 priors: HathiTrust is the largest digitised catalogue of mid-century institutional print and was expected to be the strongest single route to Elmer 1957 and Walter 1971.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (82, 'accessible-circulation-geometry', NULL, 'EN', 3, 'grey', 'intrinsic', 'https://openlibrary.org/search.json?q=wheelchair+ramps+specifications+Elmer  [then q="specifications of wheelchair ramps"]', NULL, 'openlibrary', 'scoping', NULL, 0, 0, 0, NULL, NULL, NULL, 0, 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', '2026-09-18 23:50', 'ZERO-YIELD. GENUINE ABSENCE FROM THIS INDEX: Open Library is a monograph catalogue, and a 1957 study of this kind is most likely a thesis or an institutional report, neither of which it catalogues well. ELMER 1957 REMAINS UNLOCATED AS A RECORD — but note what this batch DID learn about it from a different route: Steinfeld 1979 page 162 characterises it, so its existence and its finding are now corroborated by a primary source even though the item itself was not retrieved. A WEB SEARCH SUMMARY ASSERTED IT WAS A UNIVERSITY OF IOWA MASTER THESIS AND NOT ONE OF ITS OWN RETURNED LINKS SUPPORTED THAT; the claim is discarded, not recorded, and it is named here because CLAUDE.md section 5(c) is about exactly this shape.', 0, 'Q1 prior: Elmer 1957 locatable p~0.6, the oldest of the five and most likely a thesis or institutional report.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (83, 'accessible-circulation-geometry', NULL, 'EN', 3, 'grey', 'intrinsic', 'https://openlibrary.org/search.json?q="four architectural movement studies"  then /works/OL6527540W/editions.json', NULL, 'openlibrary', 'scoping', NULL, 1, 1, 0, NULL, NULL, NULL, 0, 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', '2026-09-18 23:50', 'RECORD CONFIRMED, FULL TEXT NOT OBTAINED — candidate 109 is now VERIFIED TO EXIST with full bibliographic detail, which it did not have when batch 17 staged it from a reference list. Open Library OL4653562M: "Four architectural movement studies for the wheelchair and ambulant disabled", by_statement "[studies directed by] Felix Walter.", published by the DISABLED LIVING FOUNDATION, 346 Kensington High St, London, 1971, 60 pp. NOTE THE AUTHOR DIVERGENCE AND ITS RESOLUTION: REF-00980 deposited reference list gives "Walter F."; the catalogue gives a corporate author with Walter as director. NEITHER IS WRONG and the batch prior named this exact risk as its dissenter clause — the reference list names the person, the catalogue names the issuing body. Recorded rather than silently picked.', 0, 'Q2 prior: Walter 1971 locatable p~0.65 — a UK research report of the kind that reaches national library catalogues. Full text p~0.25.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (84, 'accessible-circulation-geometry', NULL, 'NL', 3, 'grey', 'intrinsic', 'https://openlibrary.org/search.json?q=Voordt+ramps+accessibility  +  https://api.crossref.org/works?query.bibliographic=Accessibility+by+means+of+ramps+research+data+Netherlands  +  https://repository.tudelft.nl/search?q=Voordt%20ramps', NULL, 'openlibrary', 'scoping', NULL, 0, 0, 0, NULL, NULL, NULL, 0, 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', '2026-09-18 23:50', 'ZERO-YIELD ON ALL THREE ROUTES, AND THIS IS THE PRIOR MOST DECISIVELY FALSIFIED. I put van der Voordt 1981 at the HIGHEST retrieval odds of the five (p~0.7 record, p~0.5 full text) on the reasoning that a named academic with an institutional repository is reachable. Open Library 0; Crossref bibliographic query returned 12.7M generic results with no match; the TU Delft repository search returned nothing parseable. THE REASONING WAS WRONG IN A WAY WORTH KEEPING: an institutional repository holds what the institution deposited, and a 1981 paper predates institutional deposit entirely. Author prominence today does not make a 1981 item reachable. Candidate 111 stays PENDING-VERIFICATION.', 0, 'Q3 prior: van der Voordt 1981 locatable p~0.7 and HIGHEST chance of full text of the five (p~0.5) — a named TU Delft academic with an institutional repository.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (85, 'accessible-circulation-geometry', NULL, 'EN', 1, 'clinical', 'high_control', 'REF-01002 full-text ladder, TWO PREVIOUSLY UNATTEMPTED ROUTES ONLY: https://api.ies.ed.gov/eric/?search="running slope" AND "cross slope"  +  https://archive.org/advancedsearch.php?q="Journal of Architectural and Planning Research" AND slope', NULL, 'eric', 'scoping', NULL, 0, 0, 0, NULL, NULL, NULL, 0, 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', '2026-09-18 23:50', 'ZERO-YIELD, AND IT IS A PREDICTED RESULT RATHER THAN A FINDING. P4 put archive-route failure at p~0.8 and that is what happened. ERIC: 0. Internet Archive on the journal name: no JAPR content. GENUINE ABSENCE FROM THESE INDEXES, for the structural reason the prior gave — these archives hold public-domain and institutional material, and JAPR 2009 is neither. GAP-016 AND GAP-026 REMAIN OPEN AND UNMOVED. Batch 17 named what would actually work and it is still true: a library or document-delivery route (institutional access, ILL, or the corresponding author), which is not a search and cannot be run from this environment. TWO ROUTES FIRED, THEN STOPPED, EXACTLY AS PRE-COMMITTED — the point of the pre-commitment was to stop this batch re-running batch 17 seven routes and banking a second null as effort.', 0, 'P4, committed at 4f053bc BEFORE running: I expect the archive route to FAIL on REF-01002 at p~0.8. JAPR 26(2) 2009 is a paywalled commercial journal issue with no deposit; archives index older and greyer material, not recent commercial journals. I will fire at most two previously unattempted routes and STOP, so that a second null is scored as a predicted result and not dressed as new work.');
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-18-resea-REF-01005-MOB', 'REF-01005', 'MOB', 'Disabled adults recruited in Syracuse, NY, in the 1970s; the report groups them as wheelchair users, semi-ambulant and ambulant. This grade concerns the wheelchair-user subgroup.', 124, 'EXACT', 'EXACT on population — manual wheelchair users performing the exact task under design — and the caveats are about ERA and DENOMINATOR, not about who was studied. (1) Not a proxy: the subjects are the served population doing the designed activity. (2) THE 1:20 FIGURE RESTS ON THREE PEOPLE. The escalation design sent only those who failed 1:12 on to 1:16, and only those who failed that on to 1:20, so sample_size 124 belongs to phase 1 as a whole and must never be attached to the 1:20 row. (3) 1979 equipment cuts BOTH ways and is not a simple discount: manual chairs of that era were heavier and less efficient, so the finding that 1:12 defeats half the sample may overstate difficulty for current chairs, while the marginal-population finding may understate it for people whose equipment has not changed. (4) The report states it deliberately excluded consumer preference, limiting itself to outwardly observable behaviour because the intended use was minimum building standards — so it carries NO lived-experience warrant and is not Co-1 on any reading. Owner ruling 2026-09-18 places it as historical grounding, not a current standard.', '2026-09-18 23:55', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', 'REF-01005', NULL);
