INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (51, 'REF-01005', 'running slope', 'EN', 'Ramp — Objectives, p.52', 'the maximum slopes that can be managed', 'Harvested verbatim at the evidence stage (D-0173): a fact about what this 1979 document SAYS, not a claim that it names one of our categories. Judgment adjudicates later — GAP-033 records that adjudication has never run. NOTE the era-specific register: this source uses "the handicapped", "quadriplegics" and "hemiplegics" throughout, which are its words and must not propagate into ours.', '2026-09-18 23:55', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', '2026-09-18 23:55', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (52, 'REF-01005', 'marginal population', 'EN', 'Ramp — Marginal Population, p.53', 'Marginal Population — While all subjects in the wheelchair user group were able to manage the shallowest ramp, it was clear that steeper slopes present problems to subgroups within the total wheelchair population.', 'Harvested verbatim at the evidence stage (D-0173): a fact about what this 1979 document SAYS, not a claim that it names one of our categories. Judgment adjudicates later — GAP-033 records that adjudication has never run. NOTE the era-specific register: this source uses "the handicapped", "quadriplegics" and "hemiplegics" throughout, which are its words and must not propagate into ours.', '2026-09-18 23:55', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', '2026-09-18 23:55', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (53, 'REF-01005', 'limitations of stamina', 'EN', 'Ramp — Marginal Population, p.53', 'People with limitations of stamina, hemiplegics and quadriplegics all may have difficulty with ramps steeper than 1:20.', 'Harvested verbatim at the evidence stage (D-0173): a fact about what this 1979 document SAYS, not a claim that it names one of our categories. Judgment adjudicates later — GAP-033 records that adjudication has never run. NOTE the era-specific register: this source uses "the handicapped", "quadriplegics" and "hemiplegics" throughout, which are its words and must not propagate into ours.', '2026-09-18 23:55', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', '2026-09-18 23:55', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold');
