INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id") VALUES (115, 78, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Templer J A (1977) — the ramp-slope research REF-01005 Table 13 names as one of its two warrants', 'no DOI; named in REF-01005 Table 13 footnote c and in its Comparison with Previous Research section', NULL, 3, 0, NULL, 'HYPOTHESIS, per R15 — this description is a guess until the item is read. REF-01005 Table 13 (Maximum Lengths and Slopes for Rampways) carries footnote c: "Based on research of others (Templer, 1977 and Walter, 1971)." SO THE HUD REPORT RECOMMENDATION TABLE IS NOT FOUNDED ON ITS OWN RAMP EXPERIMENT ALONE, which is the most important structural fact this batch found about the provenance chain: the numbers that reached ANSI A117.1 came from a synthesis of three studies, only one of which this project now holds. REF-00980 deposited reference list separately holds Templer J A (1984), "Guidelines for accommodating the handicapped on crossings: final report" — a DIFFERENT item, possibly a successor. WHICH TEMPLER IS LOAD-BEARING IS UNRESOLVED AND MUST NOT BE GUESSED. Nothing in any payload this session holds names Templer institution or other work, so none is recorded. Routes to try: ERIC, NTIS, and the TRID index that already held REF-01002.', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', '2026-09-18 23:56', NULL);
