INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (52, 'REF-01005', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', NULL, 'numerical', '1:20', 'ratio', 'Every member of the wheelchair user group, including quadriplegics, was able to complete the full length of the ramp with a 1:20 slope.', 'Ramp — Findings', NULL, 'measurement_primary', 'REF-01005', NULL, NULL, NULL, NULL, NULL, 0, 'retrieval-log/session_2026-09-18-research-batch-18-archive-route-ramp-threshold/5dd866a236fb5978.pdf', 'page', NULL, NULL, '53', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'reviewed', NULL, 'THE CEILING OF THE STUDY, NOT A RECOMMENDED MAXIMUM THE AUTHORS ISSUE. n=124 disabled participants in phase 1, but the design escalated ONLY those who failed the step above: all who failed 1:12 returned for 1:16, and only those who failed THAT returned for 1:20. So the 100 percent at 1:20 rests on THREE wheelchair users (Table 11, column 1:20, reads 3 (100)). THE SENTENCE READS UNIVERSAL AND THE DENOMINATOR IS THREE, and any weighting must use the denominator rather than the sentence. Admitted T3 by OWNER RULING 2026-09-18 — 1979 work is historical grounding, not a current standard — NOT by study design, which is high-control and would otherwise derive T1. [VERBATIM-EXEMPT: OCR-NOT-DECODABLE: the artefact is a scanned 1979 microfiche (ED184280.pdf, sha256 5dd866a236fb59788dbff4b4ca80c4da8890274259b0cb6941a83c1c370fb751, bound to REF-01005 in this session manifest). quote_in_artefacts cannot decode a PDF text layer, so NO quote from this source can ever match byte-for-byte. THE BYTES DO CARRY IT and a reader can re-derive with pypdf: page index 52 holds the exact string ''complete the full length of the ramp with a 1:20 slope.'' The sentence spans a page break, page index 51 ending ''was able to''. OCR is damaged elsewhere on the page (''tncludingluadriplegics'' for ''including quadriplegics''), which is why claim_text is normalised rather than byte-exact.]', '2026-09-18 23:53', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', '2026-09-18 23:53', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (53, 'REF-01005', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', NULL, 'numerical', '1:12', 'ratio', 'As seen in Table 11, almost half of the wheelchair users were unable to negotiate the full length of the steepest ramp (1:12). Approximately one third of the test sample could not complete a distance of even 5 feet.', 'Ramp — Findings', NULL, 'measurement_primary', 'REF-01005', NULL, NULL, NULL, NULL, NULL, 0, 'retrieval-log/session_2026-09-18-research-batch-18-archive-route-ramp-threshold/5dd866a236fb5978.pdf', 'page', NULL, NULL, '52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'reviewed', NULL, 'THIS IS THE GAP-028 ANSWER AND IT IS A CODE-INSUFFICIENCY FINDING. 1:12 (8.33 percent) is the running-slope maximum of ANSI A117.1 and, through it, of ADAAG and most US-derived codes. This study was commissioned to IMPROVE that very standard — its own Foreword says the six-report series was sponsored to accomplish "making buildings accessible to and usable by the physically handicapped through improving the American National Standards Institute A117 standard" — and it measured 1:12 as unnegotiable by close to half the wheelchair users tested. UNDER THE OWNER RULING OF 2026-09-13, a finding that a code is insufficient supplies no value and is still first-class evidence. Here it supplies no value DIRECTLY (the study issues a slope/length table, not a single maximum) but it does bound the code from below. DIRECTION MATTERS AND IS COUNTER-INTUITIVE: parameter direction is lower_is_better, so a finding that 1:12 is too steep is a finding that the code floor is too LOOSE, not too tight. [VERBATIM-EXEMPT: OCR-NOT-DECODABLE: scanned 1979 microfiche ED184280.pdf (sha256 5dd866a236fb59788dbff4b4ca80c4da8890274259b0cb6941a83c1c370fb751), bound to REF-01005. quote_in_artefacts cannot decode a PDF text layer. Re-derive with pypdf at page index 51, which holds the string ''almost half of the whtelchair-users'' — OCR damage on ''wheelchair'' is why claim_text is normalised.]', '2026-09-18 23:54', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', '2026-09-18 23:54', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (54, 'REF-01005', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', NULL, 'numerical', '1:16', 'ratio', 'Walter findings for ramps are similar to ours. Both studies found a 1:16 slope for 20 feet to be accessible to at least 95 percent of the wheelchair users.', 'Comparison with Previous Research — 5. Ramps', NULL, 'measurement_primary', 'REF-01005', NULL, NULL, NULL, NULL, NULL, 0, 'retrieval-log/session_2026-09-18-research-batch-18-archive-route-ramp-threshold/5dd866a236fb5978.pdf', 'page', NULL, NULL, '163', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'reviewed', NULL, 'INDEPENDENT CONVERGENCE ACROSS TWO COUNTRIES AND EIGHT YEARS, and it is the strongest structural fact this batch found. Walter/Disabled Living Foundation 1971 (UK, candidate 109, now verified to exist as Open Library OL4653562M) and Steinfeld 1979 (US) agree that 1:16 over 20 feet is accessible to at least 95 percent of wheelchair users. THE CONVERGENCE IS THE SOURCES OWN CLAIM ABOUT A PRIOR STUDY, NOT THIS PROJECT SYNTHESIS — Walter 1971 has not been retrieved and its number is Steinfeld report of it. Do not record this as two independent rows until Walter itself is in hand; that would be counting one document twice, which is adversarial lens L3. [VERBATIM-EXEMPT: OCR-NOT-DECODABLE: scanned 1979 microfiche ED184280.pdf (sha256 5dd866a236fb59788dbff4b4ca80c4da8890274259b0cb6941a83c1c370fb751), bound to REF-01005. Re-derive with pypdf at page index 162, which holds ''Both studies found a,'' and ''1:16 slope for 20 feet to be accessibleto at least 95 percent of the'' — the OCR drops spaces, which is why claim_text is normalised.]', '2026-09-18 23:54', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', '2026-09-18 23:54', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (55, 'REF-01005', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', NULL, 'qualitative', 'steeper than 1:20 is difficult for named subgroups', NULL, 'People with limitations of stamina, hemiplegics and quadriplegics all may have difficulty with ramps steeper than 1:20. Some ambulant users with stamina limitations and walking aid users may also have difficulty with steep ramps.', 'Ramp — Marginal Population', NULL, 'measurement_primary', 'REF-01005', NULL, NULL, NULL, NULL, NULL, 0, 'retrieval-log/session_2026-09-18-research-batch-18-archive-route-ramp-threshold/5dd866a236fb5978.pdf', 'page', NULL, NULL, '53', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'reviewed', NULL, 'THE SOURCE OWN SECTION HEADING IS "Marginal Population"; the named subgroups are people with stamina limitations, hemiplegics, quadriplegics, and ambulant walking-aid users. THIS QUALIFIES THE 1:20 ROW RATHER THAN REINFORCING IT: the study says every wheelchair user completed 1:20 AND that these subgroups may have difficulty with anything steeper, which together make 1:20 a floor with no margin rather than a comfortable target. R7 applies — inadequacy captured as first-class evidence. NOTE THE ERA IN THE VOCABULARY: "quadriplegics", "hemiplegics" and "the handicapped" are the source own words, recorded because that is what a verbatim row is for; they are not this project terms and must not propagate into ours. [VERBATIM-EXEMPT: OCR-NOT-DECODABLE: scanned 1979 microfiche ED184280.pdf (sha256 5dd866a236fb59788dbff4b4ca80c4da8890274259b0cb6941a83c1c370fb751), bound to REF-01005. Re-derive with pypdf at page index 52, holding ''with ramps steeper than 1:20.'' — OCR runs words together, hence normalised claim_text.]', '2026-09-18 23:54', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', '2026-09-18 23:54', 'session_2026-09-18-research-batch-18-archive-route-ramp-threshold', 'finding', NULL);
